 const PROD_VAULT=`arn:aws:backup:${P}:${ACCT}:backup-vault:shopkaro-prod-vault`,DR_VAULT=`arn:aws:backup:${D}:${ACCT}:backup-vault:shopkaro-dr-vault`;
 const GOLDEN='ami-0a1b2c3d4e5f60001',COPY='ami-0d000000000000001',SG_PROD='sg-0bom0db00000000a1',SG_DR='sg-0hyd0db00000000a1',SG_DEFAULT='sg-0hyd0default00001';
