   a.drImages.push({id:COPY,name:'shop-web-golden-2026-10-dr',description:`[Copied ${GOLDEN} from ${P}] shop-web-golden-2026-10`,region:D,state:'available',sourceImageId:GOLDEN,sourceRegion:P,encrypted:true,kmsKey:DR_KEY,build:'release-2026.10.24'});a.drImageSequence=1;
   const r=ordersDB();delete r.fixtureId;Object.assign(r,{id:'orders-dr',name:'orders-dr',region:D,arn:`arn:aws:rds:${D}:${ACCT}:db:orders-dr`,resourceId:REPLICA_RID,endpoint:'orders-dr.sim.ap-south-2.rds.amazonaws.com',subnetGroup:'dr-private',sgIds:[SG_DR],multiAZ:false,deletionProtection:false,backupRetention:0,kmsKey:DR_KEY,source:ORDERS});
   a.rds.push(r);a.drDBSequence=1;a.drRevision=9;
